  if (filters?.priority) {
    conditions.push(`t.priority = $${paramIdx++}`);
    params.push(filters.priority);
  }
  if (filters?.tenantId) {
    conditions.push(`t."tenantId" = $${paramIdx++}`);
    params.push(filters.tenantId);
  }
