async function sendBookingConfirmationEmail(data) {
  const transporter = createTransporter();
  if (!transporter) {
    console.log("[email] SMTP n\xE3o configurado \u2014 e-mail de confirma\xE7\xE3o n\xE3o enviado.");
    return;
  }
  const rawFrom = process.env.SMTP_FROM ?? process.env.SMTP_USER;
  const from = rawFrom && rawFrom.includes("<") ? rawFrom : `"${data.shopName}" <${rawFrom}>`;
  try {
    await transporter.sendMail({
      from,
      to: data.clientEmail,
      subject: `\u2705 Agendamento confirmado \u2014 ${data.shopName}`,
      html: bookingEmailHtml(data)
    });
    console.log(`[email] Confirma\xE7\xE3o enviada para ${data.clientEmail}`);
  } catch (err) {
    console.error("[email] Erro ao enviar e-mail:", err);
  }
}
