      await createClientAccount({ clientId, email, passwordHash });
      if (lgpdConsent && tenantForReg) {
        await saveClientConsent({
          clientId,
          tenantId: tenantForReg.id,
          ipAddress: req.headers["x-forwarded-for"]?.split(",")[0]?.trim() ?? req.socket.remoteAddress ?? void 0,
          userAgent: req.headers["user-agent"]?.substring(0, 500) ?? void 0
        });
      }
      const sessionData = Buffer.from(JSON.stringify({ id: clientId, name, email })).toString("base64");
      res.cookie(`client_session_${slug}`, sessionData, { httpOnly: true, maxAge: 7 * 24 * 60 * 60 * 1e3, sameSite: "lax" });
      res.cookie("client_session", sessionData, { httpOnly: true, maxAge: 7 * 24 * 60 * 60 * 1e3, sameSite: "lax" });
