      const available = await checkSlotAvailability(barberId, date2, startTime, endTime);
      if (!available) {
        res.status(409).json({ error: "Hor\xE1rio n\xE3o dispon\xEDvel. Por favor, escolha outro hor\xE1rio." });
        return;
      }
