  app.get("/pub-api/oauth-start", (req, res) => {
    const slug = req.query.slug;
    const redirect = req.query.redirect ?? "";
    const service = req.query.service ?? "";
    const date2 = req.query.date ?? "";
    const barber = req.query.barber ?? "";
    const start = req.query.start ?? "";
    const end = req.query.end ?? "";
    const appId = process.env.VITE_APP_ID ?? "";
    const portalUrl = process.env.VITE_OAUTH_PORTAL_URL ?? "https://manus.im";
    const reqHost = req.headers["x-forwarded-host"] || req.headers.host || "localhost:3000";
    const reqProto = (req.headers["x-forwarded-proto"] || req.protocol || "http").split(",")[0].trim();
    const apiBaseUrl = process.env.PUBLIC_BASE_URL ?? process.env.EXPO_PUBLIC_API_BASE_URL ?? (reqHost.includes("localhost") ? `http://${reqHost}` : `${reqProto}://${reqHost}`);
    const callbackUrl = `${apiBaseUrl}/pub-api/oauth-callback`;
    const stateData = Buffer.from(JSON.stringify({ slug, redirect, service, date: date2, barber, start, end })).toString("base64");
    const redirectUri = callbackUrl;
    const state = Buffer.from(redirectUri).toString("base64");
    const loginUrl = new URL(`${portalUrl}/app-auth`);
    loginUrl.searchParams.set("appId", appId);
    loginUrl.searchParams.set("redirectUri", redirectUri);
    loginUrl.searchParams.set("state", state);
    loginUrl.searchParams.set("type", "signIn");
    loginUrl.searchParams.set("ctx", stateData);
    res.redirect(loginUrl.toString());
  });
  app.get("/pub-api/oauth-callback", async (req, res) => {
    const code = req.query.code;
    const state = req.query.state;
    const ctx = req.query.ctx;
    if (!code || !state) {
      res.status(400).send("Par\xE2metros inv\xE1lidos");
      return;
    }
    try {
      let slug = "", redirect = "", service = "", date2 = "", barber = "", start = "", end = "";
      if (ctx) {
        try {
          const parsed = JSON.parse(Buffer.from(ctx, "base64").toString());
          slug = parsed.slug ?? "";
          redirect = parsed.redirect ?? "";
          service = parsed.service ?? "";
          date2 = parsed.date ?? "";
          barber = parsed.barber ?? "";
          start = parsed.start ?? "";
          end = parsed.end ?? "";
        } catch {
        }
      }
      const { sdk: sdk2 } = await Promise.resolve().then(() => (init_sdk(), sdk_exports));
      const tokenResponse = await sdk2.exchangeCodeForToken(code, state);
      const userInfo = await sdk2.getUserInfo(tokenResponse.accessToken);
      if (!userInfo.email) {
        res.status(400).send("E-mail n\xE3o dispon\xEDvel na conta Google.");
        return;
      }
      let clientId = null;
      let clientName = userInfo.name ?? userInfo.email.split("@")[0];
      if (slug) {
        const tenant = await getTenantBySlug(slug);
        if (tenant) {
          const allClients = await getAllClients(tenant.id);
          const existing = allClients.find((c) => c.email === userInfo.email);
          if (existing) {
            clientId = existing.id;
            clientName = existing.name;
          } else {
            clientId = await createClient({
              name: clientName,
              email: userInfo.email,
              tenantId: tenant.id,
              isActive: true
            });
          }
        }
      }
      const sessionData = { id: clientId, name: clientName, email: userInfo.email };
      const sessionCookie = Buffer.from(JSON.stringify(sessionData)).toString("base64");
      const cookieKey = slug ? `client_session_${slug}` : "client_session";
      res.cookie(cookieKey, sessionCookie, { httpOnly: true, maxAge: 7 * 24 * 60 * 60 * 1e3, sameSite: "lax" });
      const qs = `?service=${service}&date=${date2}&barber=${barber}&start=${start}&end=${end}`;
      const target = redirect ? `/pub/${slug}/${redirect}${qs}` : `/pub/${slug}`;
      res.redirect(target);
    } catch (e) {
      console.error("[OAuth P\xFAblico] Erro:", e);
      const errCtx = req.query.ctx;
      let errSlug = "";
      try {
        if (errCtx) {
          const p = JSON.parse(Buffer.from(errCtx, "base64").toString());
          errSlug = p.slug ?? "";
        }
      } catch {
      }
      if (errSlug) {
        res.redirect(`/pub/${errSlug}/login?error=google_failed`);
      } else {
        res.status(500).send("Erro ao processar login com Google. Tente novamente.");
      }
    }
  });
