  app.post("/pub-api/forgot-password", async (req, res) => {
    try {
      const { email, slug, step, token, newPassword, confirmPassword } = req.body;
      if (!slug) {
        res.status(400).send("Slug obrigat\xF3rio");
        return;
      }
      if (step === "code") {
        const valid = await validatePasswordResetToken(email, token);
        if (!valid) {
          res.redirect(`/pub/${slug}/forgot-password?step=code&email=${encodeURIComponent(email)}&error=1`);
          return;
        }
        res.redirect(`/pub/${slug}/forgot-password?step=newPassword&email=${encodeURIComponent(email)}&token=${encodeURIComponent(token)}`);
      } else if (step === "newPassword") {
        if (!newPassword || newPassword.length < 6) {
          res.redirect(`/pub/${slug}/forgot-password?step=newPassword&email=${encodeURIComponent(email)}&token=${encodeURIComponent(token)}&error=1`);
          return;
        }
        if (newPassword !== confirmPassword) {
          res.redirect(`/pub/${slug}/forgot-password?step=newPassword&email=${encodeURIComponent(email)}&token=${encodeURIComponent(token)}&error=1`);
          return;
        }
        const consumed = await consumePasswordResetToken(email, token);
        if (!consumed) {
          res.redirect(`/pub/${slug}/forgot-password?step=code&email=${encodeURIComponent(email)}&error=1`);
          return;
        }
        const account = await getClientAccountByEmail(email);
        if (!account) {
          res.redirect(`/pub/${slug}/forgot-password?error=1`);
          return;
        }
        const passwordHash = await bcrypt2.hash(newPassword, 10);
        await updateClientAccount(account.id, { passwordHash });
        res.redirect(`/pub/${slug}/login?reset=1`);
      } else {
        const account = await getClientAccountByEmail(email);
        if (!account) {
          res.redirect(`/pub/${slug}/forgot-password?sent=1`);
          return;
        }
        const resetToken = await createPasswordResetToken(email);
        const baseUrl = process.env.PUBLIC_BASE_URL ?? `http://localhost:${process.env.PORT ?? 3e3}`;
        await sendPasswordResetEmail({ toEmail: email, token: resetToken, baseUrl });
        res.redirect(`/pub/${slug}/forgot-password?step=code&email=${encodeURIComponent(email)}&sent=1`);
      }
    } catch (e) {
      res.status(500).send("Erro interno: " + e.message);
    }
  });
