// server/_core/context.ts
init_sdk();
async function createContext(opts) {
  let user = null;
  let barber = null;
  try {
    user = await sdk.authenticateRequest(opts.req);
  } catch {
    user = null;
  }
  try {
    const token = extractBarberTokenFromRequest(opts.req);
    if (token) {
      barber = await verifyBarberToken(token);
    }
  } catch {
    barber = null;
  }
  return {
    req: opts.req,
    res: opts.res,
    user,
    barber
  };
}

