async function runReviewEmailJob() {
  try {
    const appointments2 = await getCompletedAppointmentsForReview(1.83, 4);
    if (appointments2.length === 0) return;
    console.log(`[review-job] ${appointments2.length} agendamento(s) eleg\xEDvel(is) para e-mail de avalia\xE7\xE3o`);
    const baseUrl = process.env.PUBLIC_BASE_URL ?? `http://localhost:${process.env.PORT ?? 3e3}`;
    for (const appt of appointments2) {
      try {
        const client = await getClientById(appt.clientId);
        if (!client) continue;
        const clientAccount = await getClientAccountByClientId(appt.clientId);
        const clientEmail = clientAccount?.email ?? client.email;
        if (!clientEmail) {
          await markAppointmentReviewEmailSent(appt.id);
          continue;
        }
        const service = await getServiceById(appt.serviceId);
        const barber = await getBarberById(appt.barberId);
        if (!service || !barber) continue;
        let shopSlug = "barbearia";
        let shopName = "Barber Pro";
        let googleMapsUrl = null;
        if (barber.tenantId) {
          const tenant = await getTenantById(barber.tenantId);
          if (tenant) {
            shopSlug = tenant.slug;
            shopName = tenant.name;
          }
          const tenantSettings = await getShopSettings(barber.tenantId);
          if (tenantSettings) {
            shopName = tenantSettings.shopName ?? shopName;
            googleMapsUrl = tenantSettings.googleMapsUrl ?? null;
          }
        } else {
          const settings = await getShopSettings();
          if (settings) {
            shopName = settings.shopName ?? shopName;
            googleMapsUrl = settings.googleMapsUrl ?? null;
          }
        }
        const existingReview = await getReviewByAppointmentId(appt.id);
        if (existingReview) {
          await markAppointmentReviewEmailSent(appt.id);
          continue;
        }
        await sendReviewRequestEmail({
          clientEmail,
          clientName: client.name,
          shopName,
          shopSlug,
          serviceName: service.name,
          barberName: barber.name,
          appointmentId: appt.id,
          baseUrl,
          googleMapsUrl
        });
        await markAppointmentReviewEmailSent(appt.id);
        console.log(`[review-job] E-mail de avalia\xE7\xE3o enviado para ${clientEmail} (agendamento #${appt.id})`);
      } catch (err) {
        console.error(`[review-job] Erro ao processar agendamento #${appt.id}:`, err);
      }
    }
  } catch (err) {
    console.error("[review-job] Erro no job de avalia\xE7\xE3o:", err);
  }
}
function startReviewEmailJob() {
  console.log("[review-job] Job de e-mail de avalia\xE7\xE3o iniciado (intervalo: 15 min)");
  setTimeout(runReviewEmailJob, 3e4);
  setInterval(runReviewEmailJob, JOB_INTERVAL_MS);
}

